const $ = id => document.getElementById(id);
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const safe = u => /^https?:\/\//.test(u || "") ? esc(u) : "";
const host = u => { try { return new URL(u).hostname.replace(/^www\./, ""); } catch { return "source"; } };
const money = n => "S$" + (Number.isInteger(n) ? n : n.toFixed(2));
const range = p => p.low == null ? money(p.high) : p.high == null || p.high === p.low ? money(p.low) : money(p.low) + "–" + money(p.high);
const from = p => p.low ?? p.high;
const state = { q: "", cat: null, view: "list", open: null, pin: null, here: null, say: "" };
const LATITUDE = Math.cos(1.354 * Math.PI / 180);
const JOIN_PX = 30;

DATA.shops.forEach(s => { s.hay = [s.name, s.address, ...s.services, ...s.prices.map(p => p.item + " " + (p.job || ""))].join(" ").toLowerCase(); });
DATA.categories.forEach(c => { c.hay = [c.label, ...c.words].join(" ").toLowerCase(); });
const catOf = id => DATA.categories.find(c => c.id === id);
function matchesIn(s, c) {
  if (!s.cats.includes(c.id)) return false;
  return state.q.toLowerCase().split(/\s+/).filter(Boolean).every(w => s.hay.includes(w) || c.hay.includes(w));
}
function shown() {
  const cats = state.cat ? [catOf(state.cat)] : DATA.categories;
  return cats.map(c => ({ c, items: DATA.shops.filter(s => matchesIn(s, c)) })).filter(g => g.items.length);
}
function trust(s) { return s.rating ? (s.rating.value * s.rating.count + 4.2 * 20) / (s.rating.count + 20) : -1; }
function metres(s) {
  if (!state.here || s.lat == null) return null;
  const dx = (s.lon - state.here[1]) * LATITUDE * 111320, dy = (s.lat - state.here[0]) * 110574;
  return Math.hypot(dx, dy);
}
function rank(a, b) {
  if (state.here) { const m = metres(a), n = metres(b); if (m != null || n != null) return (m ?? 1e9) - (n ?? 1e9); }
  return trust(b) - trust(a) || a.name.localeCompare(b.name);
}
function score(s) { return s.rating ? `${s.rating.value.toFixed(1)} (${s.rating.count.toLocaleString("en-SG")})` : "No rating"; }
function far(s) { const m = metres(s); return m == null ? "" : (m < 1000 ? Math.round(m / 10) * 10 + " m" : (m / 1000).toFixed(1) + " km") + " · "; }
function mapUrl(s) { return "https://www.google.com/maps/search/?api=1&query=" + encodeURIComponent(s.name + " " + (s.address || "Tampines Singapore")); }
function tel(p) { const d = p.replace(/\D/g, ""); return "tel:" + (d.length === 8 ? "+65" + d : d); }

function panel(s) {
  const facts = [["Hours", s.hours], ["Does", s.services.join(", ")], ["Check", s.note]].filter(f => f[1]).map(f => `<dt>${f[0]}</dt><dd>${esc(f[1])}</dd>`).join("");
  const prices = s.prices.length ? `<div class="block"><h3>Prices found</h3><ul class="plist">${s.prices.map(p => `<li><span>${esc(p.item)}</span><span class="amt">${range(p)}</span><span class="src">${esc(p.unit)}${p.scope === "chain" ? " · chain price, not this branch" : ""}${p.date ? " · " + esc(p.date) : ""} · <a href="${safe(p.url)}" target="_blank" rel="noopener">${esc(host(p.url))} ↗</a></span></li>`).join("")}</ul></div>` : `<p class="muted">No published price found. Ask before you commit.</p>`;
  const reviews = s.rating || s.themes.length ? `<div class="block"><h3>Reviews</h3>${s.rating ? `<p>${s.rating.value.toFixed(1)} from ${s.rating.count.toLocaleString("en-SG")} reviews on <a href="${safe(s.rating.url)}" target="_blank" rel="noopener">${esc(s.rating.platform)} ↗</a></p>` : ""}${s.themes.length ? `<ul class="themes">${s.themes.map(t => `<li>${esc(t)}</li>`).join("")}</ul>` : ""}</div>` : `<p class="muted">No reviews found.</p>`;
  const links = [...(safe(s.website) ? [`<a href="${safe(s.website)}" target="_blank" rel="noopener">Website ↗</a>`] : []), ...s.sources.filter(safe).map(u => `<a href="${safe(u)}" target="_blank" rel="noopener">${esc(host(u))} ↗</a>`)].join(", ");
  return `<div class="panel"><dl>${facts}</dl>${prices}${reviews}${links ? `<p class="muted">${links}</p>` : ""}</div>`;
}
function shopRow(s, key) {
  const open = state.open === key;
  const call = s.phone ? `<a class="button" href="${tel(s.phone)}">Call ${esc(s.phone)}</a>` : `<span class="none-call">No number on Google</span>`;
  return `<li class="shop"><button class="row" type="button" data-id="${key}" aria-expanded="${open}"><span>${esc(s.name)}</span><span class="score">${score(s)}</span><span class="where">${esc(far(s) + s.address)}</span></button><div class="acts">${call}<a class="button" href="${mapUrl(s)}" target="_blank" rel="noopener">Map ↗</a></div>${open ? panel(s) : ""}</li>`;
}
function services() {
  return `<section><ul class="list">${DATA.categories.map(c => `<li><button class="row" type="button" data-cat="${c.id}"><span>${esc(c.label)}</span><span class="count">${DATA.shops.filter(s => s.cats.includes(c.id)).length}</span></button></li>`).join("")}</ul></section>`;
}
function renderList(groups) {
  if (!state.cat && !state.q) return services();
  return groups.map(({ c, items }) => `<section><h2>${esc(c.label)} <span>${items.length}</span></h2><ul class="list">${[...items].sort(rank).map(s => shopRow(s, c.id + ":" + s.id)).join("")}</ul></section>`).join("");
}
function renderPrices(groups) {
  const parts = groups.map(({ c, items }) => {
    const jobs = new Map();
    for (const s of items) for (const p of s.prices) if (p.job && s.cats[0] === c.id) { if (!jobs.has(p.job)) jobs.set(p.job, []); jobs.get(p.job).push({ s, p }); }
    if (!jobs.size) return "";
    const body = [...jobs].sort((a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0])).map(([job, rows]) => {
      rows.sort((a, b) => from(a.p) - from(b.p));
      const best = from(rows[0].p);
      return `<div class="job"><h3>${esc(job)}</h3><p class="unit">${rows.length > 1 ? "Lowest first" : "One source"}</p><ul class="cmp">${rows.map(({ s, p }) => `<li><button type="button" data-goto="${s.id}">${esc(s.name)}</button><span class="amt ${from(p) === best && rows.length > 1 ? "low" : ""}">${range(p)}</span><span class="src">${esc(p.item)}, ${esc(p.unit)} · ${p.scope === "chain" ? "Chain price, not this branch · " : ""}${p.date ? esc(p.date) + " · " : ""}<a href="${safe(p.url)}" target="_blank" rel="noopener">${esc(host(p.url))} ↗</a></span></li>`).join("")}</ul></div>`;
    }).join("");
    return `<section><h2>${esc(c.label)}</h2>${body}</section>`;
  }).join("");
  return parts || `<p class="none">No published price for this. Open the list and call the shop.</p>`;
}

function line(pts, p) { return pts.map((q, i) => { const [x, y] = p(q[0], q[1]); return (i ? "L" : "M") + x.toFixed(1) + " " + y.toFixed(1); }).join(""); }
function renderMap(groups) {
  const seen = new Set(); const shops = [];
  for (const g of groups) for (const s of g.items) if (!seen.has(s.id)) { seen.add(s.id); shops.push(s); }
  const pinned = shops.filter(s => s.lat != null);
  if (!pinned.length) return `<p class="none">None of these shops has a map position yet.</p>`;
  const width = Math.max(320, Math.min(692, $("out").clientWidth + 32));
  let w, s0, e, n;
  {
    const pad = 0.0025;
    w = Math.min(...pinned.map(x => x.lon)) - pad; e = Math.max(...pinned.map(x => x.lon)) + pad;
    s0 = Math.min(...pinned.map(x => x.lat)) - pad; n = Math.max(...pinned.map(x => x.lat)) + pad;
    const wide = (e - w) * LATITUDE, tall = n - s0;
    if (tall < wide * 0.9) { const g = (wide * 0.9 - tall) / 2; s0 -= g; n += g; }
    if (wide < tall * 0.8) { const g = (tall * 0.8 - wide) / 2 / LATITUDE; w -= g; e += g; }
  }
  const unit = width / ((e - w) * LATITUDE), height = Math.ceil((n - s0) * unit);
  const p = (lon, lat) => [(lon - w) * LATITUDE * unit, height - (lat - s0) * unit];
  const pins = [];
  for (const s of pinned) {
    const [x, y] = p(s.lon, s.lat);
    const near = pins.find(m => (m.x - x) ** 2 + (m.y - y) ** 2 < JOIN_PX * JOIN_PX);
    if (near) { near.x = (near.x * near.list.length + x) / (near.list.length + 1); near.y = (near.y * near.list.length + y) / (near.list.length + 1); near.list.push(s); }
    else pins.push({ x, y, list: [s] });
  }
  state.pins = pins;
  const parks = GEO.parks.map(l => `<path d="${line(l, p)}Z" fill="#eef3ea"/>`).join("");
  const roads = GEO.roads.map((c, i) => c.map(l => `<path d="${line(l, p)}" fill="none" stroke="#e4e3df" stroke-width="${i === 0 ? 3 : 1.5}"/>`).join("")).join("");
  const rail = GEO.rail.map(l => `<path d="${line(l, p)}" fill="none" stroke="#b7b5ae" stroke-width="2" stroke-dasharray="6 4"/>`).join("");
  const edge = `<path d="${line(GEO.boundary, p)}Z" fill="none" stroke="#c9c8c2" stroke-width="1" stroke-dasharray="3 3"/>`;
  const taken = [];
  const labels = [...GEO.stations.map(q => [q[0] + " MRT", q[1], q[2]]), ...GEO.malls].map(([t, lon, lat]) => {
    const [x, y0] = p(lon, lat); const y = y0 - 16, wide = t.length * 6;
    if (x < 8 || x + wide > width - 8 || y < 12 || y > height - 8) return "";
    if (taken.some(b => x < b[0] + b[2] + 6 && b[0] < x + wide + 6 && Math.abs(y - b[1]) < 16)) return "";
    if (pins.some(m => m.x > x - 16 && m.x < x + wide + 16 && Math.abs(m.y - (y - 4)) < 20)) return "";
    taken.push([x, y, wide]);
    return `<text x="${x.toFixed(0)}" y="${y.toFixed(0)}">${esc(t)}</text>`;
  }).join("");
  const dots = pins.map((m, i) => { const r = m.list.length > 1 ? 13 : 7; return `<g class="pin" data-pin="${i}" data-on="${state.pin === i}" role="button" tabindex="0" aria-label="${esc(m.list.length > 1 ? m.list.length + " shops" : m.list[0].name)}"><circle cx="${m.x.toFixed(1)}" cy="${m.y.toFixed(1)}" r="22" fill="transparent"/><circle class="dot" cx="${m.x.toFixed(1)}" cy="${m.y.toFixed(1)}" r="${r}"/>${m.list.length > 1 ? `<text x="${m.x.toFixed(1)}" y="${m.y.toFixed(1)}">${m.list.length}</text>` : ""}</g>`; }).join("");
  const off = shops.length - pinned.length;
  const pick = state.pin != null && pins[state.pin] ? `<div id="pick"><h2>${pins[state.pin].list.length === 1 ? "This shop" : pins[state.pin].list.length + " shops here"}</h2><ul class="list">${[...pins[state.pin].list].sort(rank).map(s => shopRow(s, "pin:" + s.id)).join("")}</ul></div>` : "";
  return `<div class="frame"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Map of ${pinned.length} shops in Tampines">${parks}${roads}${rail}${edge}${dots}${labels}</svg></div><p class="cap">Tap a dot or a number to see the shops there. ${off ? off + " shops have no exact address, so they are not on the map. " : ""}Map data © OpenStreetMap contributors.</p>${pick}`;
}

function render() {
  const groups = shown();
  const home = !state.cat && !state.q;
  $("v-list").textContent = home ? "Services" : "Shops";
  for (const [id, v] of [["v-list", "list"], ["v-map", "map"], ["v-prices", "prices"]]) $(id).dataset.active = state.view === v;
  const back = !home ? `<button class="button" type="button" id="back">All services</button>` : "";
  const near = (!home && state.view === "list") || state.view === "map" ? `<button class="button" type="button" id="near" data-active="${!!state.here}">Nearest first</button>` : "";
    $("tools").innerHTML = back + near + (state.say ? `<span class="say">${esc(state.say)}</span>` : "");
  $("tools").hidden = !back && !near && !state.say;
  $("out").innerHTML = !groups.length ? `<p class="none">No shop matches this search. Try fewer words.</p>` : state.view === "list" ? renderList(groups) : state.view === "map" ? renderMap(groups) : renderPrices(groups);
}
function setCat(id, push) {
  state.cat = id; state.open = null; state.pin = null; state.say = "";
  if (push) { try { if (id) location.hash = id; else history.pushState(null, "", location.pathname); } catch {} }
  render(); window.scrollTo(0, 0);
}
function setView(v) { state.view = v; state.pin = null; state.open = null; render(); }
$("q").addEventListener("input", e => { state.q = e.target.value.trim(); state.open = null; state.pin = null; if (state.q && state.cat) setCat(null, true); else render(); });
$("v-list").addEventListener("click", () => setView("list"));
$("v-map").addEventListener("click", () => setView("map"));
$("v-prices").addEventListener("click", () => setView("prices"));
function locate() {
  if (state.here) { state.here = null; state.say = ""; render(); return; }
  if (!navigator.geolocation) { state.say = "This phone does not share location."; render(); return; }
  state.say = "Finding your location…"; render();
  navigator.geolocation.getCurrentPosition(p => { state.here = [p.coords.latitude, p.coords.longitude]; state.say = ""; render(); }, () => { state.say = "Location is off, so the list stays by rating."; render(); }, { timeout: 8000 });
}
document.addEventListener("click", e => {
  if (e.target.closest("#back")) { $("q").value = ""; state.q = ""; state.view = "list"; setCat(null, true); return; }
  if (e.target.closest("#near")) { locate(); return; }
  const cat = e.target.closest("[data-cat]"); if (cat) { state.view = "list"; setCat(cat.dataset.cat, true); return; }
  const go = e.target.closest("[data-goto]");
  if (go) { const s = DATA.shops.find(x => x.id === go.dataset.goto); const key = s.cats[0] + ":" + s.id; state.view = "list"; state.cat = s.cats[0]; state.q = ""; $("q").value = ""; state.open = key; render(); document.querySelector(`[data-id="${key}"]`)?.scrollIntoView({ block: "center" }); return; }
  const pin = e.target.closest("[data-pin]");
  if (pin) { state.pin = +pin.dataset.pin; state.open = null; render(); $("pick")?.scrollIntoView({ block: "nearest" }); return; }
  const row = e.target.closest(".row[data-id]");
  if (row) { const k = row.dataset.id; state.open = state.open === k ? null : k; render(); document.querySelector(`[data-id="${k}"]`)?.focus({ preventScroll: true }); }
});
document.addEventListener("keydown", e => { if ((e.key === "Enter" || e.key === " ") && e.target.closest("[data-pin]")) { e.preventDefault(); e.target.closest("[data-pin]").dispatchEvent(new MouseEvent("click", { bubbles: true })); } });
window.addEventListener("hashchange", () => { const h = location.hash.slice(1); state.view = "list"; setCat(catOf(h) ? h : null, false); });
let timer; window.addEventListener("resize", () => { clearTimeout(timer); timer = setTimeout(() => { if (state.view === "map") render(); }, 150); });
const start = location.hash.slice(1);
if (catOf(start)) state.cat = start;
const phones = DATA.shops.filter(s => s.phone).length;
$("stats").textContent = `${DATA.shops.length} shops. ${phones} phone numbers. Checked ${DATA.checked}.`;
$("foot").innerHTML = DATA.foot;
render();
